await step('Versioned price edits preview and restore as a new durable revision', async () => {
  await nav('Price cards')
  const before = await rpc('workbench/read'), original = before.config.cards[0].rates.outputTokens
  await button('Edit').click(); await field('outputTokens / 1M').fill('9'); await button('Save price card').click(); await idle()
  const edited = await rpc('workbench/read'); assert.equal(edited.priceRevision,before.priceRevision+1)
  await field('Revision to restore').selectOption(String(before.priceRevision))
  await field('I reviewed cards to restore or remove').check(); await button('Restore as new revision').click(); await idle()
  const restored=await rpc('workbench/read'); assert.equal(restored.config.cards[0].rates.outputTokens,original); assert.equal(restored.priceRevision,edited.priceRevision+1)
  assert.ok(JSON.parse(await download('Export price revision history','price-history.json')).revisions.length>=3)
})
await step('Combined observable usage and stable request identity survive ledger refresh', async () => {
  assert.equal((await page.request.post(`${base}/test/analysis`, { data: { requestId:'stable-fixture-request' } })).status(),200)
  assert.equal((await page.request.post(`${base}/test/analysis`, { data: { requestId:'stable-fixture-request' } })).status(),500)
  await button('Refresh settings and ledger').click(); await idle(); await nav('Analysis ledger')
  const ledger=(await rpc('workbench/read')).ledger; assert.equal(ledger.length,1)
  const totals=JSON.parse(await download('Export observable totals','observable-totals.json'))
  for(const key of ['uncachedInputTokens','outputTokens','cacheReadTokens','cacheWriteTokens']) assert.equal(totals.combined[key],totals.sessionUsage[key]+totals.auxiliaryUsage[key])
  assert.equal(totals.auxiliaryUsage.outputTokens,5)
})
