await step('Explicit offline receipt remains browsable with Host transport unavailable', async () => {
  await page.getByText('Offline receipts (no Host required)', { exact:true }).click()
  await button('Save current page offline').click()
  await page.route('**/rpc/**', route=>route.abort())
  await page.reload(); await page.getByText('Offline receipts (no Host required)', { exact:true }).click()
  await button('Load offline cache').click(); await page.getByRole('button', { name:/Page offset/ }).first().click()
  await expect(page.getByRole('heading', { name:'Offline historical snapshot' })).toBeVisible()
  assert.ok(!(await page.evaluate(()=>localStorage.getItem('dsh-token-usage/offline-receipts-v1'))).includes('SECRET_'))
  await page.screenshot({ path:path.join(output,'offline-receipts.png'),fullPage:true })
  await page.unroute('**/rpc/**'); await page.reload(); await idle()
